/**
 * Query Services API
 * Fetches single or multiple services with pagination and sorting.
 *
 * `queryServices` is the single entry point. It decides which underlying endpoint
 * to call based on the request: when an `availabilityFilter` is present it queries
 * the catalog-search `QueryServicesByAvailability` endpoint (cursor paging, each
 * service enriched with an `available` flag); otherwise it uses the services
 * `queryServices` endpoint (offset paging). Callers always get the same
 * `{ services, pagingMetadata }` shape.
 */
import { queryServices as queryServicesApi, LocationTypeEnumLocationType as LocationType, } from '@wix/auto_sdk_bookings_services';
import { queryServicesByFilters as queryServicesByAvailabilitySdk, LocationType as AvailabilityLocationType, } from '@wix/auto_sdk_bookings_catalog-search';
import { BOOKING_APP_ID, DEFAULT_QUERY_LIMIT, } from '../../services/constants.js';
/**
 * Synthetic location ID constants for non-business locations
 */
export const SYNTHETIC_CUSTOM_ID = 'custom';
export const SYNTHETIC_CUSTOMER_ID = 'customer';
/**
 * Re-exported availability filter types so consumers can build availability UIs
 * without importing the ambassador package directly.
 */
export { AvailabilityLocationType, };
/**
 * Fetches a service by its ID
 * @param id - The service ID
 * @param appId - Optional app ID, defaults to booking app ID
 * @returns Object containing the service or null if not found
 */
export const getServiceById = async (id, appId) => {
    try {
        const finalAppId = appId ?? BOOKING_APP_ID;
        // Query services where _id equals the provided id and appId matches
        const query = queryServicesApi({
            conditionalFields: ['STAFF_MEMBER_DETAILS'],
        });
        const result = await query
            .eq('_id', id)
            // @ts-ignore
            .eq('appId', finalAppId)
            .limit(1)
            .find();
        const service = result.items?.[0] || null;
        return { service };
    }
    catch (error) {
        console.error(`Failed to load service for id "${id}":`, error);
        return { service: null };
    }
};
/**
 * Fetches a service by its slug
 * @param slug - The service slug
 * @param appId - Optional app ID, defaults to booking app ID
 * @returns Object containing the service or null if not found
 */
export const getServiceBySlug = async (slug, appId) => {
    try {
        const finalAppId = appId ?? BOOKING_APP_ID;
        // Query services where mainSlug.name equals the provided slug and appId matches
        const query = queryServicesApi({
            conditionalFields: ['STAFF_MEMBER_DETAILS'],
        });
        const result = await query
            .eq('mainSlug.name', slug)
            // @ts-ignore
            .eq('appId', finalAppId)
            .limit(1)
            .find();
        const service = result.items?.[0] || null;
        return { service };
    }
    catch (error) {
        console.error(`Failed to load service for slug "${slug}":`, error);
        return { service: null };
    }
};
/**
 * Extracts an array of values from a platform Filter field that may use operators like $in or $hasSome.
 * @param fieldValue - The filter field value (can be direct value, array, or operator object)
 * @returns Array of string values extracted from the filter
 */
function extractArrayFromFilterField(fieldValue) {
    if (!fieldValue)
        return [];
    // Direct array value
    if (Array.isArray(fieldValue)) {
        return fieldValue.map(String);
    }
    // Operator object with $in or $hasSome
    if (typeof fieldValue === 'object' && fieldValue !== null) {
        const operatorObj = fieldValue;
        // Use bracket notation for index signature access
        if (Array.isArray(operatorObj['$in'])) {
            return operatorObj['$in'].map(String);
        }
        if (Array.isArray(operatorObj['$hasSome'])) {
            return operatorObj['$hasSome'].map(String);
        }
        // $eq operator with single value
        if (operatorObj['$eq'] !== undefined) {
            return [String(operatorObj['$eq'])];
        }
    }
    // Direct single value
    if (typeof fieldValue === 'string' || typeof fieldValue === 'number') {
        return [String(fieldValue)];
    }
    return [];
}
/**
 * Converts a platform Filter object to the API filter format expected by the Bookings services API.
 * Handles special cases like location filtering where synthetic locations need to be converted
 * to location types.
 *
 * @param platformFilter - Platform Filter object with standard operators ($in, $hasSome, $eq, etc.)
 * @returns API filter object ready for the Bookings query API
 *
 * @example
 * ```ts
 * // Input (Platform Filter)
 * {
 *   'category.id': { $in: ['cat1', 'cat2'] },
 *   'locations.business.id': { $hasSome: ['loc1', 'custom'] }
 * }
 *
 * // Output (API Filter)
 * {
 *   'category.id': { $in: ['cat1', 'cat2'] },
 *   'locations.business.id': { $hasSome: ['loc1'] },
 *   'locations.type': { $hasSome: ['CUSTOM'] }
 * }
 * ```
 */
export function convertPlatformFilterToApiFilter(platformFilter) {
    if (!platformFilter)
        return {};
    const apiFilter = {};
    for (const [fieldPath, fieldValue] of Object.entries(platformFilter)) {
        if (fieldValue === null || fieldValue === undefined)
            continue;
        // Special handling for location filters - need to split synthetic vs business locations
        if (fieldPath === 'locations.business.id') {
            const locationIds = extractArrayFromFilterField(fieldValue);
            if (locationIds.length === 0)
                continue;
            const syntheticTypes = [];
            const businessLocationIds = [];
            for (const id of locationIds) {
                if (id === SYNTHETIC_CUSTOM_ID) {
                    syntheticTypes.push(LocationType.CUSTOM);
                }
                else if (id === SYNTHETIC_CUSTOMER_ID) {
                    syntheticTypes.push(LocationType.CUSTOMER);
                }
                else {
                    businessLocationIds.push(id);
                }
            }
            // Add location type filter for synthetic locations
            if (syntheticTypes.length > 0) {
                apiFilter['locations.type'] = { $hasSome: syntheticTypes };
            }
            // Add business location filter for real locations
            if (businessLocationIds.length > 0) {
                apiFilter['locations.business.id'] = { $hasSome: businessLocationIds };
            }
        }
        else {
            // Pass through all other filters directly - the platform Filter format
            // is compatible with the Bookings API filter format
            apiFilter[fieldPath] = fieldValue;
        }
    }
    return apiFilter;
}
/**
 * Builds a QueryServicesRequest from appId, filter, paging, and sort
 * @param params - Parameters including appId, filter (platform Filter type), paging, and sort
 * @returns QueryServicesRequest object for the SDK
 */
const buildServicesQueryRequest = ({ appId, filter: platformFilter, paging, sort, }) => {
    // Start with appId as base filter
    const filter = {
        appId,
    };
    // Convert platform filter to API format and merge
    if (platformFilter) {
        const apiFilter = convertPlatformFilterToApiFilter(platformFilter);
        Object.assign(filter, apiFilter);
    }
    const query = {
        filter: Object.keys(filter).length > 0 ? filter : undefined,
        paging: paging || {
            limit: DEFAULT_QUERY_LIMIT,
        },
        sort,
    };
    return { query };
};
/**
 * Whether an availability filter carries a real bookable constraint that warrants
 * routing to the availability endpoint. Modifiers that don't define a query on their
 * own (`timeZone`, `exactMatch`, `includeUnavailable`) are ignored: only a complete
 * date window (both `localStartDate` and `localEndDate`) or a resource constraint
 * (`locations`/`attributes`/`resourceTypes`) counts.
 *
 * This is the single source of truth shared by the API dispatch and the service's
 * `hasAvailabilityFilterSignal`.
 */
export function hasActiveAvailabilityFilter(availabilityFilter) {
    if (!availabilityFilter)
        return false;
    const { localStartDate, localEndDate, locationIds, attributes, resourceTypes, } = availabilityFilter;
    const hasDateWindow = Boolean(localStartDate && localEndDate);
    const hasResourceConstraint = (locationIds?.length ?? 0) > 0 ||
        (attributes?.length ?? 0) > 0 ||
        (resourceTypes?.length ?? 0) > 0;
    return hasDateWindow || hasResourceConstraint;
}
/**
 * Queries services by real bookable availability (catalog-search). Cursor-based.
 * The WQL filter reuses the same platform→API conversion as the offset query.
 */
async function queryServicesByAvailability({ appId, filter, availabilityFilter, sort, pagingMetadata, }) {
    const wqlFilter = {
        appId: appId ?? BOOKING_APP_ID,
    };
    if (filter) {
        Object.assign(wqlFilter, convertPlatformFilterToApiFilter(filter));
    }
    const limit = pagingMetadata?.limit ?? DEFAULT_QUERY_LIMIT;
    const cursor = pagingMetadata?.cursor;
    const availabilityQuery = {
        filter: wqlFilter,
        sort,
        cursorPaging: { limit, ...(cursor ? { cursor } : {}) },
    };
    const response = await queryServicesByAvailabilitySdk({
        query: availabilityQuery,
        serviceFilters: availabilityFilter,
    });
    const results = response.results ?? [];
    return {
        services: results.map((result) => ({
            ...result.service,
            available: result.available ?? true,
        })),
        pagingMetadata: {
            limit,
            count: response.pagingMetadata?.count ?? results.length,
            hasNext: response.pagingMetadata?.hasNext ?? false,
            cursor: response.pagingMetadata?.cursors?.next ?? undefined,
        },
    };
}
/**
 * Query services with pagination and sorting.
 * Picks the underlying endpoint by request: availability filter present → catalog-search
 * (cursor paging, `available` flag); otherwise the offset services query.
 *
 * @param request - Query parameters including appId, filter (platform Filter type), paging
 *   metadata, sort options, and an optional availability filter
 * @returns Promise that resolves to services array and paging metadata with hasNext flag
 *
 * @example
 * ```ts
 * // Offset query
 * const { services, pagingMetadata } = await queryServices({
 *   appId: '13d21c63-b5ec-5912-8397-c3a5ddb27a97',
 *   filter: { '_id': { $in: ['service1', 'service2'] } },
 *   pagingMetadata: { limit: 20, offset: 0 },
 * });
 *
 * // Availability-aware query (cursor paging + `available` flag)
 * const availability = await queryServices({
 *   appId: '13d21c63-b5ec-5912-8397-c3a5ddb27a97',
 *   availabilityFilter: { localStartDate: '...', localEndDate: '...', timeZone: '...' },
 *   pagingMetadata: { limit: 20 },
 * });
 * ```
 */
export async function queryServices(request) {
    const { appId, filter, pagingMetadata, sort, availabilityFilter } = request;
    // Decide the endpoint by the filters passed.
    if (hasActiveAvailabilityFilter(availabilityFilter)) {
        return queryServicesByAvailability(request);
    }
    try {
        const queryRequest = buildServicesQueryRequest({
            appId,
            filter,
            paging: pagingMetadata,
            sort,
        });
        // Call queryServices with QueryServicesRequest and execute the query
        // Include conditionalFields to fetch staff member details
        const result = await queryServicesApi({
            ...queryRequest,
            conditionalFields: ['STAFF_MEMBER_DETAILS'],
        }).find();
        // Construct PagingMetadata from result properties
        // Includes count (number of items returned) and hasNext (whether more items are available)
        const resultPagingMetadata = {
            limit: pagingMetadata?.limit,
            offset: pagingMetadata?.offset,
            count: result.items.length,
            hasNext: (result?.totalCount || 0) >
                result.items.length + (pagingMetadata?.offset || 0),
        };
        return {
            services: result.items || [],
            pagingMetadata: resultPagingMetadata,
        };
    }
    catch (error) {
        console.error('Failed to query services:', error);
        throw error;
    }
}
